// PostToolUse playbook — inspect tool output for compliance signals.
// MVP: scan tool_output stderr/stdout for known failure patterns; if file
// edit landed in story scope, queue a nudge for the next Stop to surface
// a deeper review.
//
// Future: LLM scoring of edit diff vs story_rulesets.rule_ids (mid-tier
// model, low temperature).
const body = $input.first().json.body || $input.first().json;
if (body.event !== 'post_tool') {
  throw new Error(`WF_DIRIGENT_COMPLIANCE_ENFORCEMENT expects event=post_tool, got ${body.event}`);
}
const toolInput = body.tool_input || {};
const toolOutput = body.tool_output || {};
const filePath = String(toolInput.file_path || '');
const output = String(toolOutput.stderr || toolOutput.stdout || toolOutput.output || '');

const failureSignals = [
  { pattern: /error TS\d+/, kind: 'ts-error', note: 'TypeScript chyba v build outputu' },
  { pattern: /FAIL\s+|✗\s|✘\s/, kind: 'test-fail', note: 'Test failure' },
  { pattern: /eslint.*error/i, kind: 'lint-error', note: 'ESLint violation' },
  { pattern: /npm\s+run\s+db:(reset|refreshdb)|drop\s+(?:table|database)|truncate\s+table/i, kind: 'destructive-op', note: 'destruktivní DB operace v outputu' }
];

const hits = failureSignals.filter(s => s.pattern.test(output)).map(s => ({ kind: s.kind, note: s.note }));

let advisory = '';
let nudgeQueued = false;
if (hits.length > 0) {
  advisory = `⚠️ AISHA Enforcement: po nástroji detekuji ${hits.length} signál(ů) — ${hits.map(h => h.note).join('; ')}.`;
} else if (filePath && body.story_id) {
  // Soft hint that a file landed inside story scope; nudge is the durable persistence
  nudgeQueued = true;
}
return [{
  json: {
    advisory,
    decision: 'allow',
    nudge_queued: nudgeQueued,
    nudge: nudgeQueued ? { story_id: body.story_id, conversation_id: body.session_id, event_origin: 'compliance_engine', severity: 'info', message: `Edit landed: ${filePath}. Bude přepáčen na příští Stop evaluaci.` } : null,
    _audit: { event: 'post_tool', story_id: body.story_id, session_id: body.session_id, file_path: filePath, hits_count: hits.length, nudge_queued: nudgeQueued }
  }
}];
